import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../../core/services/auth.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.scss'],
})
export class LoginComponent implements OnInit {
  loginForm!: FormGroup;
  isLoading = false;
  errorMessage = '';
  showPassword = false;

  roles = ['General User', 'Admin'];

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private router: Router
  ) {}

  ngOnInit(): void {
    if (this.authService.isLoggedIn()) {
      this.router.navigate(['/dashboard']);
    }

    this.loginForm = this.fb.group({
      userId:   ['', [Validators.required, Validators.minLength(3)]],
      password: ['', [Validators.required, Validators.minLength(6)]],
      role:     ['General User', Validators.required],
    });
  }

  onSubmit(): void {
    if (this.loginForm.invalid) {
      this.loginForm.markAllAsTouched();
      return;
    }

    this.isLoading = true;
    this.errorMessage = '';

    this.authService.login(this.loginForm.value).subscribe({
      next: (res) => {
        this.isLoading = false;
        if (res.user.role === 'Admin') {
          this.router.navigate(['/admin']);
        } else {
          this.router.navigate(['/dashboard']);
        }
      },
      error: (err) => {
        this.isLoading = false;
        this.errorMessage = err.error?.message || 'Login failed. Please try again.';
      },
    });
  }

  get f() {
    return this.loginForm.controls;
  }

  togglePassword(): void {
    this.showPassword = !this.showPassword;
  }
}
<div class="login-wrapper">
  <div class="login-left">
    <div class="brand">
      <div class="brand-logo">NSQ</div>
      <h1>NSQTech Portal</h1>
      <p>Secure access to your workspace. Manage records, users, and more.</p>
    </div>
    <div class="feature-list">
      <div class="feature-item">
        <span class="icon">🔐</span>
        <span>Role-based access control</span>
      </div>
      <div class="feature-item">
        <span class="icon">📊</span>
        <span>Real-time record management</span>
      </div>
      <div class="feature-item">
        <span class="icon">👥</span>
        <span>Admin user management</span>
      </div>
    </div>
  </div>

  <div class="login-right">
    <div class="login-card">
      <div class="login-header">
        <h2>Welcome Back</h2>
        <p>Sign in to your account</p>
      </div>

      <form [formGroup]="loginForm" (ngSubmit)="onSubmit()" novalidate>

        <!-- User ID -->
        <div class="form-group">
          <label for="userId">User ID</label>
          <div class="input-wrapper">
            <span class="input-icon">👤</span>
            <input
              id="userId"
              type="text"
              formControlName="userId"
              placeholder="Enter your User ID"
              [class.error]="f['userId'].invalid && f['userId'].touched"
            />
          </div>
          <div class="error-msg" *ngIf="f['userId'].invalid && f['userId'].touched">
            <span *ngIf="f['userId'].errors?.['required']">User ID is required.</span>
            <span *ngIf="f['userId'].errors?.['minlength']">Minimum 3 characters.</span>
          </div>
        </div>

        <!-- Password -->
        <div class="form-group">
          <label for="password">Password</label>
          <div class="input-wrapper">
            <span class="input-icon">🔒</span>
            <input
              id="password"
              [type]="showPassword ? 'text' : 'password'"
              formControlName="password"
              placeholder="Enter your password"
              [class.error]="f['password'].invalid && f['password'].touched"
            />
            <button type="button" class="toggle-pwd" (click)="togglePassword()">
              {{ showPassword ? '🙈' : '👁️' }}
            </button>
          </div>
          <div class="error-msg" *ngIf="f['password'].invalid && f['password'].touched">
            <span *ngIf="f['password'].errors?.['required']">Password is required.</span>
            <span *ngIf="f['password'].errors?.['minlength']">Minimum 6 characters.</span>
          </div>
        </div>

        <!-- Role -->
        <div class="form-group">
          <label for="role">Role</label>
          <div class="input-wrapper">
            <span class="input-icon">🎭</span>
            <select id="role" formControlName="role">
              <option *ngFor="let r of roles" [value]="r">{{ r }}</option>
            </select>
          </div>
        </div>

        <!-- Error alert -->
        <div class="alert-error" *ngIf="errorMessage">
          ⚠️ {{ errorMessage }}
        </div>

        <!-- Submit -->
        <button type="submit" class="btn-login" [disabled]="isLoading">
          <span *ngIf="!isLoading">Sign In →</span>
          <span *ngIf="isLoading" class="loading-dots">Signing in<span>.</span><span>.</span><span>.</span></span>
        </button>

      </form>

      <div class="login-hint">
        <p><strong>Demo Credentials:</strong></p>
        <p>Admin → <code>admin001</code> / <code>Admin@123</code></p>
        <p>User  → <code>user001</code> / <code>User@123</code></p>
      </div>
    </div>
  </div>
</div>
